#!/usr/bin/env bash
# Fetches the third-party sources that are too large to keep in git.
#
# BLAKE3, toml++ and a minimal Boost subset are committed directly to this
# directory, so the only thing that has to be fetched is gperftools, pinned by
# version and verified by SHA-256.
#
# The Boost subset (930 of 15,828 headers) is regenerated by
# regen-boost-subset.sh, not by this script.
#
#   ./fetch.sh            fetch anything missing
#   ./fetch.sh --force    re-fetch even if already present

set -euo pipefail

TP="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DL="$TP/.dl"

GPERF_VERSION="2.16"
GPERF_URL="https://github.com/gperftools/gperftools/releases/download/gperftools-${GPERF_VERSION}/gperftools-${GPERF_VERSION}.tar.gz"
GPERF_SHA256="f12624af5c5987f2cc830ee534f754c3c5961eec08004c26a8b80de015cf056f"
GPERF_DIR="$TP/gperftools"

FORCE=0
[[ "${1:-}" == "--force" ]] && FORCE=1

log() { printf '>> %s\n' "$*"; }

verify() {
  local file="$1" expected="$2"
  local actual
  actual="$(sha256sum "$file" | cut -d' ' -f1)"
  if [[ "$actual" != "$expected" ]]; then
    echo "checksum mismatch for $file" >&2
    echo "  expected $expected" >&2
    echo "  actual   $actual" >&2
    return 1
  fi
}

download() {
  local url="$1" out="$2"
  [[ -f "$out" ]] && return 0
  log "downloading $(basename "$out")"
  curl -sSL --fail -o "$out" "$url"
}

mkdir -p "$DL"

# ---- gperftools (tcmalloc_minimal, built static) ----------------------------

if [[ $FORCE -eq 1 || ! -f "$GPERF_DIR/build/libtcmalloc_minimal.a" ]]; then
  download "$GPERF_URL" "$DL/gperftools.tar.gz"
  verify "$DL/gperftools.tar.gz" "$GPERF_SHA256"
  # A path that exists but is not a directory -- a stray file, or a symlink
  # whose target is not present here -- makes the mv below fail with a message
  # that describes the symptom and not the cause. Clear it instead: nothing
  # under this path is authored, it is all re-fetchable.
  if [[ -e "$GPERF_DIR" || -L "$GPERF_DIR" ]] && [[ ! -d "$GPERF_DIR" ]]; then
    log "replacing non-directory $GPERF_DIR"
    rm -f "$GPERF_DIR"
  fi
  if [[ ! -d "$GPERF_DIR" ]]; then
    log "extracting gperftools"
    tar xzf "$DL/gperftools.tar.gz" -C "$DL"
    mv "$DL/gperftools-${GPERF_VERSION}" "$GPERF_DIR"
  fi
  log "building tcmalloc_minimal"
  cmake -S "$GPERF_DIR" -B "$GPERF_DIR/build" \
        -DCMAKE_BUILD_TYPE=Release \
        -DBUILD_SHARED_LIBS=OFF \
        -DGPERFTOOLS_BUILD_STATIC=ON \
        -DGPERFTOOLS_BUILD_HEAP_PROFILER=OFF \
        -DGPERFTOOLS_BUILD_HEAP_CHECKER=OFF \
        -DGPERFTOOLS_BUILD_CPU_PROFILER=OFF \
        -DGPERFTOOLS_BUILD_DEBUGALLOC=OFF \
        -DCMAKE_POSITION_INDEPENDENT_CODE=ON >/dev/null
  cmake --build "$GPERF_DIR/build" -j"$(nproc)" --target tcmalloc_minimal common >/dev/null
else
  log "tcmalloc_minimal already built"
fi

log "third-party dependencies ready"
